import assert from 'node:assert/strict';
import { Session } from './src/session.js';
const tick=()=>Promise.resolve().then(()=>Promise.resolve());
const timers={schedule(fn){queueMicrotask(fn)}};
let calls=[];
const offline=new Session({timers,queryFn(ctx){calls.push(ctx.signal);return Promise.resolve('unexpected')}},{online:false});
const h=offline.subscribe('fresh');
assert.equal(offline.snapshot('fresh').fetchStatus,'paused');
offline.unsubscribe(h);
assert.equal(offline.snapshot('fresh').fetchStatus,'idle');
offline.online(true);
await tick();
assert.equal(calls.length,0);

let resolve;
const background=new Session({timers,queryFn(){return new Promise(r=>{resolve=r})}});
const b=background.subscribe('background');
background.unsubscribe(b);
resolve('cached');
await tick();
assert.deepEqual(background.snapshot('background'),{status:'success',fetchStatus:'idle',data:'cached'});

let seen;
const consumed=new Session({timers,queryFn(ctx){seen=ctx.signal;return new Promise(()=>{})}});
const c=consumed.subscribe('consumed');
consumed.unsubscribe(c);
assert.equal(seen.aborted,true);
assert.deepEqual(consumed.snapshot('consumed'),{status:'pending',fetchStatus:'idle',data:null});

let continuations=0;
const gated=new Session({timers,queryFn(){continuations++;return Promise.resolve('x')}},{online:false});
const g=gated.subscribe('gate');
gated.online(true);
gated.focus(false);
await tick();
assert.equal(continuations,0);
gated.focus(true);
await tick();
assert.equal(continuations,1);
gated.unsubscribe(g);
console.log('session lifecycle assertions passed');
